static
void kernel_trisolv(int n,
		    DATA_TYPE POLYBENCH_2D(L,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(b,N,n))
{
  int i, j;

#pragma scop
  {
    /* Loop skewing / wavefront transformation of the triangular solve:
       the original i-loop carries dependencies (x[i] needs all x[j],
       j < i).  Skewing exposes a wavefront where, at step t, x[t]
